<script setup>
import { computed, onMounted, ref } from 'vue';
import { adminApi } from '@/api';
import ConfirmDialog from '@/components/common/ConfirmDialog.vue';
import { useToast } from '@/stores/toast';
import { buildGoodsReceiptPayload, goodsReceiptPreview, goodsReceiptTotal, validateGoodsReceipt } from '@/utils/inventoryOperations';
import { formatQuantity } from '@/utils/inventoryItem';

const toast = useToast();
const receipts = ref([]);
const inventoryItems = ref([]);
const loading = ref(true);
const loadError = ref('');
const saving = ref(false);
const formError = ref('');
const editingId = ref(null);
const confirmation = ref(null);
const form = ref(blankForm());
const itemById = computed(() => new Map(inventoryItems.value.map((item) => [item.inventoryItemId, item])));
const sortedReceipts = computed(() => [...receipts.value].sort((a, b) => (a.status === 'DRAFT' ? 0 : 1) - (b.status === 'DRAFT' ? 0 : 1)));
const documentTotal = computed(() => goodsReceiptTotal(form.value.items));

function localDateTime() { const date = new Date(); date.setMinutes(date.getMinutes() - date.getTimezoneOffset()); return date.toISOString().slice(0, 16); }
function blankLine() { return { inventoryItemId: '', purchaseQuantity: '', purchaseUnit: '', conversionFactor: '1', purchaseUnitPrice: '' }; }
function blankForm() { return { supplierName: '', invoiceNumber: '', receivedAt: localDateTime(), items: [blankLine()] }; }
function money(value) { return Number(value).toLocaleString('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }); }
async function load() { loading.value = true; loadError.value = ''; try { const [list, items] = await Promise.all([adminApi.getGoodsReceipts(), adminApi.getInventoryItems()]); receipts.value = Array.isArray(list) ? list : []; inventoryItems.value = Array.isArray(items) ? items : []; } catch (error) { loadError.value = error.message || 'Không thể tải phiếu nhập'; } finally { loading.value = false; } }
function addLine() { form.value.items.push(blankLine()); }
function removeLine(index) { if (form.value.items.length > 1) form.value.items.splice(index, 1); }
function resetForm() { editingId.value = null; form.value = blankForm(); formError.value = ''; }
async function editReceipt(receipt) { formError.value = ''; try { const detail = await adminApi.getGoodsReceipt(receipt.goodsReceiptId); editingId.value = detail.goodsReceiptId; form.value = { supplierName: detail.supplierName, invoiceNumber: detail.invoiceNumber || '', receivedAt: String(detail.receivedAt).slice(0, 16), items: detail.items.map((line) => ({ ...line, inventoryItemId: String(line.inventoryItemId), purchaseQuantity: String(line.purchaseQuantity), conversionFactor: String(line.conversionFactor), purchaseUnitPrice: String(line.purchaseUnitPrice) })) }; document.querySelector('#receipt-form')?.scrollIntoView({ behavior: 'smooth' }); } catch (error) { formError.value = error.message || 'Không thể mở phiếu nhập'; } }
async function save() { const errors = validateGoodsReceipt(form.value); if (Object.keys(errors).length) { formError.value = Object.values(errors)[0]; return; } saving.value = true; formError.value = ''; try { const payload = buildGoodsReceiptPayload(form.value); if (editingId.value) await adminApi.updateGoodsReceipt(editingId.value, payload); else await adminApi.createGoodsReceipt(payload); toast.success(editingId.value ? 'Đã cập nhật phiếu nhập' : 'Đã tạo phiếu nhập nháp'); resetForm(); await load(); } catch (error) { formError.value = error.message || 'Không thể lưu phiếu nhập'; } finally { saving.value = false; } }
function requestConfirmation(kind, receipt) { confirmation.value = { kind, receipt }; }
async function approve(receipt) { saving.value = true; try { await adminApi.approveGoodsReceipt(receipt.goodsReceiptId); toast.success('Đã duyệt phiếu nhập'); resetForm(); await load(); } catch (error) { loadError.value = error.message || 'Không thể duyệt phiếu nhập'; } finally { saving.value = false; confirmation.value = null; } }
async function remove(receipt) { saving.value = true; try { await adminApi.deleteGoodsReceipt(receipt.goodsReceiptId); if (editingId.value === receipt.goodsReceiptId) resetForm(); await load(); } catch (error) { loadError.value = error.message || 'Không thể xóa phiếu nhập'; } finally { saving.value = false; confirmation.value = null; } }
function confirmAction() { const { kind, receipt } = confirmation.value; return kind === 'approve' ? approve(receipt) : remove(receipt); }
onMounted(load);
</script>

<template>
  <main class="ops-page">
    <header class="page-heading"><div><p class="eyebrow">Nhập hàng</p><h1>Ghi nhận hàng vừa nhận</h1><p>Đi lần lượt ba bước. Phiếu chỉ tăng tồn kho sau khi duyệt.</p></div><button class="btn btn-outline" :disabled="loading" @click="load">Làm mới</button></header>
    <section id="receipt-form" class="panel">
      <div class="section-heading"><h2>{{ editingId ? `Sửa phiếu #${editingId}` : 'Tạo phiếu nhập' }}</h2><button v-if="editingId" class="btn btn-sm btn-outline" type="button" @click="resetForm">Tạo phiếu mới</button></div>
      <form @submit.prevent="save">
        <fieldset><legend><span>1</span> Thông tin giao hàng</legend><div class="form-grid"><label>Nhà cung cấp<input v-model="form.supplierName" class="form-input" maxlength="150" required /></label><label>Số hóa đơn<input v-model="form.invoiceNumber" class="form-input" maxlength="100" /></label><label>Thời gian nhận<input v-model="form.receivedAt" class="form-input" type="datetime-local" required /></label></div></fieldset>
        <fieldset><legend><span>2</span> Nguyên liệu nhận được</legend><div v-for="(line,index) in form.items" :key="index" class="line-card">
          <label>Mặt hàng<select v-model="line.inventoryItemId" class="form-select" required><option value="">Chọn mặt hàng</option><option v-for="item in inventoryItems" :key="item.inventoryItemId" :value="String(item.inventoryItemId)">{{ item.inventoryCode }} · {{ item.name }} ({{ item.baseUnit }})</option></select></label>
          <label>Số lượng mua<input v-model="line.purchaseQuantity" class="form-input" type="number" min="0.0001" step="0.0001" required /></label><label>Đơn vị mua<input v-model="line.purchaseUnit" class="form-input" maxlength="30" placeholder="thùng, kg..." required /></label><label>Mỗi đơn vị mua có<input v-model="line.conversionFactor" class="form-input" type="number" min="0.0001" step="0.0001" required /></label><label>Đơn giá mua<input v-model="line.purchaseUnitPrice" class="form-input" type="number" min="0.0001" step="0.0001" required /></label>
          <p class="conversion">{{ formatQuantity(line.purchaseQuantity) }} {{ line.purchaseUnit || 'đơn vị mua' }} sẽ thành <strong>{{ formatQuantity(goodsReceiptPreview(line).baseQuantity) }} {{ itemById.get(Number(line.inventoryItemId))?.baseUnit || 'đơn vị kho' }}</strong>.</p>
          <div class="preview" aria-live="polite"><span>Tăng tồn kho <strong>{{ formatQuantity(goodsReceiptPreview(line).baseQuantity) }}</strong></span><span>Thành tiền dòng <strong>{{ goodsReceiptPreview(line).lineTotal == null ? '—' : money(goodsReceiptPreview(line).lineTotal) }}</strong></span><span>Chi phí mỗi đơn vị cơ sở <strong>{{ goodsReceiptPreview(line).baseUnitCost == null ? '—' : money(goodsReceiptPreview(line).baseUnitCost) }}</strong></span></div>
          <button class="btn btn-sm btn-outline" type="button" :disabled="form.items.length === 1" :aria-label="`Bỏ dòng ${index + 1}`" @click="removeLine(index)">Bỏ</button>
        </div><button class="btn btn-sm btn-outline" type="button" @click="addLine">+ Thêm nguyên liệu</button></fieldset>
        <fieldset class="review-fieldset"><legend><span>3</span> Kiểm tra & duyệt</legend><div class="document-total" aria-live="polite"><span>Tổng tiền phiếu</span><strong>{{ money(documentTotal) }}</strong></div><p>Lưu nháp để kiểm tra lại. Sau đó duyệt phiếu trong danh sách bên dưới.</p></fieldset>
        <p v-if="formError" class="error-box" role="alert">{{ formError }}</p><div class="actions"><button class="btn btn-primary" :disabled="saving">{{ saving ? 'Đang lưu...' : 'Lưu nháp an toàn' }}</button></div>
      </form>
    </section>
    <section class="panel"><div class="section-heading"><div><h2>Phiếu cần xử lý</h2><p class="muted">Phiếu nháp được đưa lên trước.</p></div></div><div v-if="loading" class="state" role="status">Đang tải...</div><div v-else-if="loadError" class="state error" role="alert">{{ loadError }} <button class="btn btn-sm btn-outline" @click="load">Thử lại</button></div><div v-else-if="!receipts.length" class="state">Chưa có phiếu nhập.</div><div v-else class="table-wrapper"><table class="table"><thead><tr><th>Mã</th><th>Nhà cung cấp</th><th>Hóa đơn</th><th>Ngày nhận</th><th>Dòng</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="receipt in sortedReceipts" :key="receipt.goodsReceiptId" :class="{ locked: receipt.status !== 'DRAFT' }"><td data-label="Mã">#{{ receipt.goodsReceiptId }}</td><td data-label="Nhà cung cấp"><strong>{{ receipt.supplierName }}</strong></td><td data-label="Hóa đơn">{{ receipt.invoiceNumber || '—' }}</td><td data-label="Ngày nhận">{{ receipt.receivedAt }}</td><td data-label="Dòng">{{ receipt.items.length }}</td><td data-label="Trạng thái"><span class="badge" :class="receipt.status === 'DRAFT' ? 'badge-warning' : 'badge-success'">{{ receipt.status === 'DRAFT' ? 'Nháp · cần kiểm tra' : 'Đã duyệt' }}</span></td><td data-label="Thao tác"><div v-if="receipt.status === 'DRAFT'" class="row-actions"><button class="btn btn-sm btn-outline" @click="editReceipt(receipt)">Sửa</button><button class="btn btn-sm btn-primary" @click="requestConfirmation('approve', receipt)">Duyệt</button><button class="btn btn-sm btn-outline" @click="requestConfirmation('delete', receipt)">Xóa</button></div><span v-else class="locked-label"><i class="bi bi-lock" aria-hidden="true"></i> Phiếu đã khóa</span></td></tr></tbody></table></div></section>
    <ConfirmDialog :open="Boolean(confirmation)" :busy="saving" :title="confirmation?.kind === 'approve' ? `Duyệt phiếu #${confirmation.receipt.goodsReceiptId}?` : `Xóa phiếu nháp #${confirmation?.receipt.goodsReceiptId}?`" :message="confirmation?.kind === 'approve' ? 'Sau khi duyệt, số lượng tồn kho và giá vốn sẽ được cập nhật. Phiếu không thể sửa lại.' : 'Phiếu nháp sẽ bị xóa và không ảnh hưởng tồn kho.'" :confirm-label="confirmation?.kind === 'approve' ? 'Duyệt và nhập kho' : 'Xóa phiếu'" @confirm="confirmAction" @cancel="confirmation = null" />
  </main>
</template>

<style scoped>
.ops-page{display:grid;gap:20px;min-width:0;overflow-x:hidden}.page-heading,.section-heading,.actions,.row-actions{display:flex;align-items:center;justify-content:space-between;gap:10px}.page-heading h1{margin:2px 0;font-size:28px}.page-heading p{margin:0;color:var(--text-mid)}.eyebrow{color:var(--role-admin)!important;font-size:11px!important;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.panel{min-width:0;background:#fff;border:1px solid var(--border-light);border-radius:14px;padding:20px;display:grid;gap:14px}.panel h2{margin:0;font-size:18px}form,fieldset,.form-grid,.line-card,label{min-width:0}form{display:grid;gap:16px}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}label{display:grid;gap:6px;color:var(--text-mid);font-size:12px;font-weight:700}label :is(input,select){width:100%;min-width:0;box-sizing:border-box}fieldset{border:1px solid var(--border-light);border-radius:12px;padding:16px;display:grid;gap:12px}legend{font-size:14px;font-weight:800;padding:0 8px}legend span{display:inline-grid;place-items:center;width:26px;height:26px;margin-right:6px;border-radius:50%;background:var(--primary);color:#fff}.line-card{display:grid;grid-template-columns:2fr repeat(4,minmax(0,1fr)) auto;gap:10px;align-items:end;padding:12px;background:var(--surface);border-radius:10px}.conversion,.preview{grid-column:1/-2;margin:0;overflow-wrap:anywhere}.conversion{font-size:13px}.preview{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;color:var(--text-mid)}.review-fieldset{background:#fffaf6}.review-fieldset p{margin:0;color:var(--text-mid)}.document-total{display:flex;justify-content:space-between;gap:12px;font-size:16px}.document-total strong{font-size:22px}.actions{justify-content:flex-end}.error-box{color:#b91c1c;background:#fef2f2;padding:10px;border-radius:8px}.state{padding:34px;text-align:center;color:var(--text-mid)}.error{color:#b91c1c}.table-wrapper{overflow-x:auto}.table{min-width:900px}.locked{background:var(--surface);color:var(--text-mid)}.locked-label,.muted{color:var(--text-mid)}.ops-page :is(button,input,select):focus-visible{outline:3px solid var(--primary);outline-offset:2px}.ops-page :is(button,input,select){min-height:40px}@media(max-width:900px){.form-grid{grid-template-columns:1fr}.line-card{grid-template-columns:repeat(2,minmax(0,1fr))}.line-card label:first-child,.conversion,.preview{grid-column:1/-1}.table-wrapper{overflow:visible}.table{min-width:0}.table thead{display:none}.table,.table tbody,.table tr,.table td{display:block;width:100%;box-sizing:border-box}.table tr{padding:14px;border-bottom:1px solid var(--border-light)}.table td{display:grid;grid-template-columns:minmax(90px,100px) minmax(0,1fr);gap:10px;padding:6px 0;border:0}.table td:before{content:attr(data-label);color:var(--text-mid);font-size:12px}}@media(max-width:600px){.panel{padding:14px}.page-heading{align-items:flex-start;flex-direction:column}.line-card{grid-template-columns:minmax(0,1fr)}.line-card>*{grid-column:1!important}.row-actions{justify-content:flex-start}}
</style>
